package kimi

import (
	"encoding/json"
	"os"
	"path/filepath"
	"testing"
)

// TestRemoteAsarMatchesTheReleasedBuild compares the Go archive against the one
// the released build produced for the same input. The fixture is generated by
// `remote-bundle.mjs`, so a byte difference is a real divergence, not a
// formatting choice.
func TestRemoteAsarMatchesTheReleasedBuild(t *testing.T) {
	inputData, err := os.ReadFile(filepath.Join("testdata", "remote", "asar-input.json"))
	if err != nil {
		t.Fatal(err)
	}
	var files map[string]string
	if err := json.Unmarshal(inputData, &files); err != nil {
		t.Fatal(err)
	}
	payloads := map[string][]byte{}
	for name, content := range files {
		payloads[name] = []byte(content)
	}
	// The released build lists package.json first, then bootstrap.mjs.
	result, err := BuildRemoteAsar(payloads, []string{"package.json", "bootstrap.mjs"})
	if err != nil {
		t.Fatal(err)
	}
	expected, err := os.ReadFile(filepath.Join("testdata", "remote", "expected-asar.bin"))
	if err != nil {
		t.Fatal(err)
	}
	expectedHeader, err := os.ReadFile(filepath.Join("testdata", "remote", "expected-asar-header.txt"))
	if err != nil {
		t.Fatal(err)
	}
	if result.HeaderHash != string(expectedHeader) {
		t.Fatalf("header hash: %s want %s", result.HeaderHash, expectedHeader)
	}
	if len(result.Data) != len(expected) {
		t.Fatalf("length: %d want %d", len(result.Data), len(expected))
	}
	for i := range result.Data {
		if result.Data[i] != expected[i] {
			t.Fatalf("byte %d differs: %02x want %02x", i, result.Data[i], expected[i])
		}
	}
}

func TestReadRemoteAsarEntryRoundTrips(t *testing.T) {
	payloads := map[string][]byte{
		"package.json":  []byte(`{"name":"x","version":"1.0.0"}`),
		"bootstrap.mjs": []byte("import { app } from 'electron';\n"),
	}
	result, err := BuildRemoteAsar(payloads, []string{"package.json", "bootstrap.mjs"})
	if err != nil {
		t.Fatal(err)
	}
	for name, want := range payloads {
		got, ok := ReadRemoteAsarEntry(result.Data, name)
		if !ok {
			t.Fatalf("%s not readable", name)
		}
		if string(got) != string(want) {
			t.Fatalf("%s: %q want %q", name, got, want)
		}
	}
	if _, ok := ReadRemoteAsarEntry(result.Data, "absent"); ok {
		t.Fatal("an absent entry was read")
	}
}

func TestRemoteAsarRejectsAnInvalidEntryName(t *testing.T) {
	for _, name := range []string{"", "../escape", "a/b", "a b", "a\\b"} {
		if _, err := BuildRemoteAsar(map[string][]byte{name: []byte("x")}, []string{name}); err == nil {
			t.Fatalf("accepted %q", name)
		}
	}
}

func TestRemoteAsarIsDeterministic(t *testing.T) {
	payloads := map[string][]byte{"a.js": []byte("one"), "b.js": []byte("two")}
	order := []string{"a.js", "b.js"}
	first, _ := BuildRemoteAsar(payloads, order)
	second, _ := BuildRemoteAsar(payloads, order)
	if first.HeaderHash != second.HeaderHash || len(first.Data) != len(second.Data) {
		t.Fatal("the archive is not deterministic")
	}
}

func TestRemoteBundleIdentityValidation(t *testing.T) {
	for _, good := range []string{"dev.kimi-work-gateway.remote", "dev.kimi-work-gateway.credentials"} {
		if !RemoteBundleIdentityValid(good) {
			t.Fatalf("rejected %s", good)
		}
	}
	for _, bad := range []string{"", "com.example.app", "dev.kimi-work-gateway.", "dev.kimi-work-gateway.REMOTE"} {
		if RemoteBundleIdentityValid(bad) {
			t.Fatalf("accepted %q", bad)
		}
	}
}

func TestVerifyBundleSignatureIsFalseOffMacOS(t *testing.T) {
	previous := runtimeGOOS
	runtimeGOOS = func() string { return "windows" }
	defer func() { runtimeGOOS = previous }()
	// An unverifiable bundle must never be reported as verified.
	if VerifyBundleSignature("/nonexistent") {
		t.Fatal("a bundle was reported verified without a verifier")
	}
}

func TestVerifyBundleSignatureRejectsAnUnsignedBundle(t *testing.T) {
	if runtimeGOOS() != "darwin" {
		t.Skip("codesign is macOS only")
	}
	if VerifyBundleSignature(t.TempDir()) {
		t.Fatal("an unsigned directory was reported verified")
	}
}

func TestVerifyRemoteBundleMetadata(t *testing.T) {
	metadata := map[string]any{"CFBundleIdentifier": "dev.kimi-work-gateway.remote", "CFBundleExecutable": "Kimi"}
	if !VerifyRemoteBundleMetadata(metadata, "dev.kimi-work-gateway.remote", "Kimi") {
		t.Fatal("valid metadata was refused")
	}
	if VerifyRemoteBundleMetadata(metadata, "dev.kimi-work-gateway.other", "Kimi") {
		t.Fatal("a wrong identifier was accepted")
	}
	if VerifyRemoteBundleMetadata(metadata, "dev.kimi-work-gateway.remote", "Other") {
		t.Fatal("a wrong executable was accepted")
	}
	if VerifyRemoteBundleMetadata(map[string]any{}, "dev.kimi-work-gateway.remote", "Kimi") {
		t.Fatal("empty metadata was accepted")
	}
}
